import{_ as e,c as r,o as a,a0 as i}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively.","frontmatter":{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively."},"headers":[],"relativePath":"da/blog/team-communication.md","filePath":"da/blog/team-communication.md"}');const t=e({name:"da/blog/team-communication.md"},[["render",function(e,n,t,l,o,s){return a(),r("div",null,[...n[0]||(n[0]=[i('<h1 id="kommunikation-under-pres" tabindex="-1">Kommunikation under pres <a class="header-anchor" href="#kommunikation-under-pres" aria-label="Permalink to &quot;Kommunikation under pres&quot;">​</a></h1><p>I petanque kan kommunikation være afgørende for et holds succes eller fiasko. De rigtige ord på det rigtige tidspunkt skaber selvtillid og klarhed. De forkerte ord – eller tavshed, når der er brug for ord – kan ødelægge selv dygtige hold.</p><h2 id="hvorfor-kommunikation-er-vigtig" tabindex="-1">Hvorfor kommunikation er vigtig <a class="header-anchor" href="#hvorfor-kommunikation-er-vigtig" aria-label="Permalink to &quot;Hvorfor kommunikation er vigtig&quot;">​</a></h2><p>Petanque-hold står over for unikke kommunikationsudfordringer:</p><ul><li>Beslutninger skal træffes hurtigt</li><li>Pres påvirker, hvordan vi taler og lytter</li><li>Nonverbale signaler er synlige for modstandere</li><li>Individuel præstation påvirker holddynamikken</li></ul><p>Effektiv kommunikation skaber:</p><ul><li>Fælles forståelse af strategi</li><li>Gensidig støtte og tillid</li><li>Hurtig og klar beslutningstagning</li><li>Modstandsdygtighed gennem svære øjeblikke</li></ul><h2 id="kommunikationsprincipperne" tabindex="-1">Kommunikationsprincipperne <a class="header-anchor" href="#kommunikationsprincipperne" aria-label="Permalink to &quot;Kommunikationsprincipperne&quot;">​</a></h2><h3 id="_1-klarhed-frem-for-kvantitet" tabindex="-1">1. Klarhed frem for kvantitet <a class="header-anchor" href="#_1-klarhed-frem-for-kvantitet" aria-label="Permalink to &quot;1. Klarhed frem for kvantitet&quot;">​</a></h3><p>Under pres er mindre mere. Klar og præcis kommunikation er bedre end lange diskussioner:</p><p><strong>I stedet for:</strong> &quot;Jeg tror måske, vi skulle prøve at pege her, men jeg er ikke sikker på, hvad synes du, terrænet ser vanskeligt ud...&quot;</p><p><strong>Sig:</strong> &quot;Jeg peger mod venstre side. Jorden er bedre der.&quot;</p><h3 id="_2-positiv-indramning" tabindex="-1">2. Positiv indramning <a class="header-anchor" href="#_2-positiv-indramning" aria-label="Permalink to &quot;2. Positiv indramning&quot;">​</a></h3><p>Indram kommunikationen konstruktivt:</p><p><strong>I stedet for:</strong> &quot;Gå ikke glip af denne her&quot; <strong>Sig:</strong> &quot;Du klarer det her – stol på dit kast&quot;</p><p><strong>I stedet for:</strong> &quot;Det var forfærdeligt&quot; <strong>Sig:</strong> &quot;Ryst det af dig, den næste&quot;</p><h3 id="_3-nuværende-fokus" tabindex="-1">3. Nuværende fokus <a class="header-anchor" href="#_3-nuværende-fokus" aria-label="Permalink to &quot;3. Nuværende fokus&quot;">​</a></h3><p>Hold kommunikationen fokuseret på det, der kommer, ikke det, der er fortid:</p><p><strong>I stedet for:</strong> &quot;Hvorfor smed du den der?&quot; <strong>Sig:</strong> &quot;Okay, hvad er vores bedste mulighed nu?&quot;</p><h3 id="_4-ejerskabssprog" tabindex="-1">4. Ejerskabssprog <a class="header-anchor" href="#_4-ejerskabssprog" aria-label="Permalink to &quot;4. Ejerskabssprog&quot;">​</a></h3><p>Brug &quot;jeg&quot;-udsagn til dine egne handlinger, &quot;vi&quot; til teamsituationer:</p><ul><li>&quot;Jeg tager dette skud&quot;</li><li>&quot;Vi skal beskytte pointen&quot;</li><li>&quot;Jeg synes, vi burde...&quot;</li></ul><h2 id="hvad-skal-man-kommunikere" tabindex="-1">Hvad skal man kommunikere <a class="header-anchor" href="#hvad-skal-man-kommunikere" aria-label="Permalink to &quot;Hvad skal man kommunikere&quot;">​</a></h2><h3 id="før-hver-ende" tabindex="-1">Før hver ende <a class="header-anchor" href="#før-hver-ende" aria-label="Permalink to &quot;Før hver ende&quot;">​</a></h3><ul><li><strong>Strategidiskussion</strong>: Kort afstemning om tilgang</li><li><strong>Rolleklarhed</strong>: Hvem gør hvad</li><li><strong>Terrænobservationer</strong>: Relevante forhold</li></ul><h3 id="under-afspilning" tabindex="-1">Under afspilning <a class="header-anchor" href="#under-afspilning" aria-label="Permalink to &quot;Under afspilning&quot;">​</a></h3><ul><li><strong>Beslutninger</strong>: Tydelig erklæring om den påtænkte handling</li><li><strong>Støtte</strong>: Opmuntring før kast</li><li><strong>Information</strong>: Relevante observationer om terræn eller modstandere</li></ul><h3 id="efter-kast" tabindex="-1">Efter kast <a class="header-anchor" href="#efter-kast" aria-label="Permalink to &quot;Efter kast&quot;">​</a></h3><ul><li><strong>Anerkendelse</strong>: Kort anerkendelse (god eller dårlig)</li><li><strong>Justering</strong>: Eventuelle nødvendige strategiske ændringer</li><li><strong>Nulstil</strong>: Hjælp holdkammerater med at fokusere igen</li></ul><h2 id="hvad-man-ikke-skal-kommunikere" tabindex="-1">Hvad man IKKE skal kommunikere <a class="header-anchor" href="#hvad-man-ikke-skal-kommunikere" aria-label="Permalink to &quot;Hvad man IKKE skal kommunikere&quot;">​</a></h2><h3 id="undga-under-presmomenter" tabindex="-1">Undgå under presmomenter <a class="header-anchor" href="#undga-under-presmomenter" aria-label="Permalink to &quot;Undgå under presmomenter&quot;">​</a></h3><ul><li>Tekniske instruktioner (&quot;Hold albuen inde&quot;)</li><li>Kritik af tidligere kast</li><li>Udtryk for frustration</li><li>Tvivl om holdkammeratens evner</li><li>Overdreven analyse</li></ul><h3 id="undga-generelt" tabindex="-1">Undgå generelt <a class="header-anchor" href="#undga-generelt" aria-label="Permalink to &quot;Undgå generelt&quot;">​</a></h3><ul><li>Skyld sprog</li><li>Sarkasme eller passiv aggression</li><li>Sammenligninger med andre spillere</li><li>Forudsigelser om fiasko</li></ul><h2 id="nonverbal-kommunikation" tabindex="-1">Nonverbal kommunikation <a class="header-anchor" href="#nonverbal-kommunikation" aria-label="Permalink to &quot;Nonverbal kommunikation&quot;">​</a></h2><p>Dit kropssprog taler højt:</p><h3 id="positive-signaler" tabindex="-1">Positive signaler <a class="header-anchor" href="#positive-signaler" aria-label="Permalink to &quot;Positive signaler&quot;">​</a></h3><ul><li>Øjenkontakt med holdkammerater</li><li>Åben, afslappet kropsholdning</li><li>Nikken og anerkendelsen</li><li>Rolige, stabile bevægelser</li></ul><h3 id="negative-signaler-undga" tabindex="-1">Negative signaler (undgå) <a class="header-anchor" href="#negative-signaler-undga" aria-label="Permalink to &quot;Negative signaler (undgå)&quot;">​</a></h3><ul><li>Øjenrulning eller suk</li><li>Vender sig væk fra holdkammeraterne</li><li>Krydsede arme eller lukket kropsholdning</li><li>Synlig frustration</li></ul><h3 id="læsende-holdkammerater" tabindex="-1">Læsende holdkammerater <a class="header-anchor" href="#læsende-holdkammerater" aria-label="Permalink to &quot;Læsende holdkammerater&quot;">​</a></h3><p>Lær at genkende, hvornår holdkammerater har brug for:</p><ul><li><strong>Mellemrum</strong>: De behandler, afbryd ikke</li><li><strong>Støtte</strong>: De kæmper, tilbyd opmuntring</li><li><strong>Information</strong>: De er usikre, giv klarhed</li><li><strong>Energi</strong>: De er flade, bringer entusiasme</li></ul><h2 id="kommunikationsroller" tabindex="-1">Kommunikationsroller <a class="header-anchor" href="#kommunikationsroller" aria-label="Permalink to &quot;Kommunikationsroller&quot;">​</a></h2><h3 id="pegeren" tabindex="-1">Pegeren <a class="header-anchor" href="#pegeren" aria-label="Permalink to &quot;Pegeren&quot;">​</a></h3><ul><li>Kommunikér din læsning af terrænet</li><li>Angiv tydeligt din ønskede placering</li><li>Bed om input, når du er usikker</li></ul><h3 id="skytteren" tabindex="-1">Skytteren <a class="header-anchor" href="#skytteren" aria-label="Permalink to &quot;Skytteren&quot;">​</a></h3><ul><li>Bekræft valg af mål</li><li>Kommunikér selvtillidsniveau</li><li>Anmod om information om vinkler</li></ul><h3 id="miljøet-kaptajnen" tabindex="-1">Miljøet/Kaptajnen <a class="header-anchor" href="#miljøet-kaptajnen" aria-label="Permalink to &quot;Miljøet/Kaptajnen&quot;">​</a></h3><ul><li>Facilitere teamdiskussioner</li><li>Træf endelige beslutninger, når det er nødvendigt</li><li>Styr teamets energi og fokus</li></ul><h2 id="pressede-situationer" tabindex="-1">Pressede situationer <a class="header-anchor" href="#pressede-situationer" aria-label="Permalink to &quot;Pressede situationer&quot;">​</a></h2><h3 id="nar-du-er-bagud" tabindex="-1">Når du er bagud <a class="header-anchor" href="#nar-du-er-bagud" aria-label="Permalink to &quot;Når du er bagud&quot;">​</a></h3><ul><li>Forbliv løsningsfokuseret</li><li>Bevar positiv energi</li><li>Undgå bebrejdelse eller frustration</li><li>Fejr små sejre</li></ul><h3 id="nar-forude" tabindex="-1">Når forude <a class="header-anchor" href="#nar-forude" aria-label="Permalink to &quot;Når forude&quot;">​</a></h3><ul><li>Hold fokus, undgå selvtilfredshed</li><li>Hold kommunikationen konsekvent</li><li>Lav ikke om på det, der virker</li></ul><h3 id="matchpoint-deres" tabindex="-1">Matchpoint (deres) <a class="header-anchor" href="#matchpoint-deres" aria-label="Permalink to &quot;Matchpoint (deres)&quot;">​</a></h3><ul><li>Anerkend presset kort</li><li>Fokuser på processen</li><li>Støt hinanden synligt</li></ul><h3 id="matchpoint-vores" tabindex="-1">Matchpoint (vores) <a class="header-anchor" href="#matchpoint-vores" aria-label="Permalink to &quot;Matchpoint (vores)&quot;">​</a></h3><ul><li>Forbliv rolig og fokuseret</li><li>Undgå for tidlig fejring</li><li>Udfør som normalt</li></ul><h2 id="opbygning-af-kommunikationsevner" tabindex="-1">Opbygning af kommunikationsevner <a class="header-anchor" href="#opbygning-af-kommunikationsevner" aria-label="Permalink to &quot;Opbygning af kommunikationsevner&quot;">​</a></h2><h3 id="i-praksis" tabindex="-1">I praksis <a class="header-anchor" href="#i-praksis" aria-label="Permalink to &quot;I praksis&quot;">​</a></h3><ul><li>Øv kommunikation under træning</li><li>Giv og modtag feedback på kommunikation</li><li>Eksperimentér med forskellige tilgange</li></ul><h3 id="teamaftaler" tabindex="-1">Teamaftaler <a class="header-anchor" href="#teamaftaler" aria-label="Permalink to &quot;Teamaftaler&quot;">​</a></h3><p>Etabler teamnormer:</p><ul><li>Hvordan vi håndterer uenigheder</li><li>Sådan ser støtten ud</li><li>Hvornår man skal tale, og hvornår man skal tie stille</li></ul><h3 id="gennemgang-efter-kampen" tabindex="-1">Gennemgang efter kampen <a class="header-anchor" href="#gennemgang-efter-kampen" aria-label="Permalink to &quot;Gennemgang efter kampen&quot;">​</a></h3><p>Diskuter kommunikation:</p><ul><li>Hvad fungerede godt?</li><li>Hvad kunne forbedres?</li><li>Nogle misforståelser at rette op på?</li></ul><h2 id="nar-kommunikationen-bryder-sammen" tabindex="-1">Når kommunikationen bryder sammen <a class="header-anchor" href="#nar-kommunikationen-bryder-sammen" aria-label="Permalink to &quot;Når kommunikationen bryder sammen&quot;">​</a></h2><h3 id="i-øjeblikket" tabindex="-1">I øjeblikket <a class="header-anchor" href="#i-øjeblikket" aria-label="Permalink to &quot;I øjeblikket&quot;">​</a></h3><ol><li>Tag en indånding</li><li>Nulstil med en simpel sætning: &quot;Lad os fokusere på dette kast&quot;</li><li>Tilbage til det grundlæggende: klar, positiv, nærværende</li></ol><h3 id="efter-kampen" tabindex="-1">Efter kampen <a class="header-anchor" href="#efter-kampen" aria-label="Permalink to &quot;Efter kampen&quot;">​</a></h3><ul><li>Håndter problemerne roligt</li><li>Fokuser på adfærd, ikke personligheder</li><li>Enighed om forbedringer</li><li>Gå fremad sammen</li></ul><h2 id="den-stille-støtte" tabindex="-1">Den stille støtte <a class="header-anchor" href="#den-stille-støtte" aria-label="Permalink to &quot;Den stille støtte&quot;">​</a></h2><p>Nogle gange er den bedste kommunikation tilstedeværelse:</p><ul><li>Står sammen med en holdkammerat, der kæmper</li><li>En hånd på skulderen</li><li>Et nik af tillid</li><li>Bare at være der</li></ul><p>Ord er ikke altid nødvendige. Forbindelse er.</p><hr><p>| <em>Relateret: <a href="/da/uddannelse/holdspiller/">Holddynamik</a> | <a href="/da/uddannelse/holdspiller/kommunikation">Kommunikation</a> | <a href="/da/uddannelse/mental-styrke/håndtering-af-pres">Håndtering af pres</a></em> |</p>',79)])])}]]);export{n as __pageData,t as default};
